// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Create a care group; caller becomes Admin
	// (POST /care-groups)
	CreateCareGroup(ctx context.Context, request CreateCareGroupRequestObject) (CreateCareGroupResponseObject, error)
	// Invite a user to the care group by email (admin only)
	// (POST /care-groups/{careGroupId}/invitations)
	CreateInvitation(ctx context.Context, request CreateInvitationRequestObject) (CreateInvitationResponseObject, error)
	// Revoke a pending invitation (admin only)
	// (DELETE /care-groups/{careGroupId}/invitations/{token})
	RevokeInvitation(ctx context.Context, request RevokeInvitationRequestObject) (RevokeInvitationResponseObject, error)
	// List the members of a care group (any member)
	// (GET /care-groups/{careGroupId}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// Add a receiver to a care group (admin only)
	// (POST /care-groups/{careGroupId}/receivers)
	CreateReceiver(ctx context.Context, request CreateReceiverRequestObject) (CreateReceiverResponseObject, error)
	// Return evaluated feature flags
	// (GET /flags)
	GetFlags(ctx context.Context, request GetFlagsRequestObject) (GetFlagsResponseObject, error)
	// Health check
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// Pending invitations for the caller's verified email
	// (GET /invitations/mine)
	ListMyInvitations(ctx context.Context, request ListMyInvitationsRequestObject) (ListMyInvitationsResponseObject, error)
	// Accept an invitation by token; creates a membership
	// (POST /invitations/{token}/accept)
	AcceptInvitation(ctx context.Context, request AcceptInvitationRequestObject) (AcceptInvitationResponseObject, error)
	// Current user and their care-group memberships
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// List receivers across the caller's groups (optionally one group)
	// (GET /receivers)
	ListReceivers(ctx context.Context, request ListReceiversRequestObject) (ListReceiversResponseObject, error)
	// Archive a receiver (admin only)
	// (DELETE /receivers/{receiverId})
	ArchiveReceiver(ctx context.Context, request ArchiveReceiverRequestObject) (ArchiveReceiverResponseObject, error)
	// Get a receiver
	// (GET /receivers/{receiverId})
	GetReceiver(ctx context.Context, request GetReceiverRequestObject) (GetReceiverResponseObject, error)
	// Update a receiver (admin only)
	// (PATCH /receivers/{receiverId})
	UpdateReceiver(ctx context.Context, request UpdateReceiverRequestObject) (UpdateReceiverResponseObject, error)
	// List a receiver's scheduled items across trackers, soonest first (paginated)
	// (GET /receivers/{receiverId}/scheduled-items)
	ListReceiverScheduledItems(ctx context.Context, request ListReceiverScheduledItemsRequestObject) (ListReceiverScheduledItemsResponseObject, error)
	// List a receiver's trackers
	// (GET /receivers/{receiverId}/trackers)
	ListTrackers(ctx context.Context, request ListTrackersRequestObject) (ListTrackersResponseObject, error)
	// Create a tracker for a receiver (admin only)
	// (POST /receivers/{receiverId}/trackers)
	CreateTracker(ctx context.Context, request CreateTrackerRequestObject) (CreateTrackerResponseObject, error)
	// Delete a scheduled item
	// (DELETE /scheduled-items/{scheduledItemId})
	DeleteScheduledItem(ctx context.Context, request DeleteScheduledItemRequestObject) (DeleteScheduledItemResponseObject, error)
	// Get a single scheduled item
	// (GET /scheduled-items/{scheduledItemId})
	GetScheduledItem(ctx context.Context, request GetScheduledItemRequestObject) (GetScheduledItemResponseObject, error)
	// Reschedule or edit a scheduled item
	// (PUT /scheduled-items/{scheduledItemId})
	UpdateScheduledItem(ctx context.Context, request UpdateScheduledItemRequestObject) (UpdateScheduledItemResponseObject, error)
	// List the seeded tracker-template catalog
	// (GET /tracker-templates)
	ListTrackerTemplates(ctx context.Context, request ListTrackerTemplatesRequestObject) (ListTrackerTemplatesResponseObject, error)
	// Archive a tracker (admin only)
	// (DELETE /trackers/{trackerId})
	ArchiveTracker(ctx context.Context, request ArchiveTrackerRequestObject) (ArchiveTrackerResponseObject, error)
	// Get a tracker
	// (GET /trackers/{trackerId})
	GetTracker(ctx context.Context, request GetTrackerRequestObject) (GetTrackerResponseObject, error)
	// Update a tracker (admin only)
	// (PATCH /trackers/{trackerId})
	UpdateTracker(ctx context.Context, request UpdateTrackerRequestObject) (UpdateTrackerResponseObject, error)
	// List a tracker's events, newest first (paginated)
	// (GET /trackers/{trackerId}/events)
	ListEvents(ctx context.Context, request ListEventsRequestObject) (ListEventsResponseObject, error)
	// Log an event against a tracker
	// (POST /trackers/{trackerId}/events)
	LogEvent(ctx context.Context, request LogEventRequestObject) (LogEventResponseObject, error)
	// Delete a logged event
	// (DELETE /trackers/{trackerId}/events/{eventId})
	DeleteEvent(ctx context.Context, request DeleteEventRequestObject) (DeleteEventResponseObject, error)
	// Get a single event
	// (GET /trackers/{trackerId}/events/{eventId})
	GetEvent(ctx context.Context, request GetEventRequestObject) (GetEventResponseObject, error)
	// Edit a logged event
	// (PATCH /trackers/{trackerId}/events/{eventId})
	UpdateEvent(ctx context.Context, request UpdateEventRequestObject) (UpdateEventResponseObject, error)
	// List a tracker's scheduled items, soonest first (paginated)
	// (GET /trackers/{trackerId}/scheduled-items)
	ListScheduledItems(ctx context.Context, request ListScheduledItemsRequestObject) (ListScheduledItemsResponseObject, error)
	// Add a scheduled item to a scheduled tracker
	// (POST /trackers/{trackerId}/scheduled-items)
	CreateScheduledItem(ctx context.Context, request CreateScheduledItemRequestObject) (CreateScheduledItemResponseObject, error)
	// Join a care team as a caregiver, by invite code
	// (POST /v1/invitations/redeem)
	RedeemInvitation(ctx context.Context, request RedeemInvitationRequestObject) (RedeemInvitationResponseObject, error)
	// The signed-in caregiver and the care teams they belong to
	// (GET /v1/me)
	GetMyAccount(ctx context.Context, request GetMyAccountRequestObject) (GetMyAccountResponseObject, error)
	// Pending invitations addressed to the caller's verified email
	// (GET /v1/me/invitations)
	ListInvitationsForMe(ctx context.Context, request ListInvitationsForMeRequestObject) (ListInvitationsForMeResponseObject, error)
	// Every tracker of one care receiver, active and paused
	// (GET /v1/receivers/{receiverId}/trackers)
	ListReceiverTrackers(ctx context.Context, request ListReceiverTrackersRequestObject) (ListReceiverTrackersResponseObject, error)
	// Create a tracker for an active care receiver (admin only)
	// (POST /v1/receivers/{receiverId}/trackers)
	AddTracker(ctx context.Context, request AddTrackerRequestObject) (AddTrackerResponseObject, error)
	// Remove this schedule? — Remove (admin only)
	// (DELETE /v1/schedules/{scheduleId})
	RemoveSchedule(ctx context.Context, request RemoveScheduleRequestObject) (RemoveScheduleResponseObject, error)
	// A schedule's Save, for an existing schedule (admin only)
	// (PUT /v1/schedules/{scheduleId})
	ChangeSchedule(ctx context.Context, request ChangeScheduleRequestObject) (ChangeScheduleResponseObject, error)
	// Create a care team; the caller becomes its first admin
	// (POST /v1/teams)
	CreateTeam(ctx context.Context, request CreateTeamRequestObject) (CreateTeamResponseObject, error)
	// The care team's care receivers, oldest first
	// (GET /v1/teams/{teamId}/receivers)
	ListTeamReceivers(ctx context.Context, request ListTeamReceiversRequestObject) (ListTeamReceiversResponseObject, error)
	// The tracker template catalogue
	// (GET /v1/tracker-templates)
	ListTemplates(ctx context.Context, request ListTemplatesRequestObject) (ListTemplatesResponseObject, error)
	// One tracker, with what is wrong with it right now
	// (GET /v1/trackers/{trackerId})
	GetTrackerDetail(ctx context.Context, request GetTrackerDetailRequestObject) (GetTrackerDetailResponseObject, error)
	// Edit tracker's Save (admin only)
	// (PUT /v1/trackers/{trackerId})
	EditTracker(ctx context.Context, request EditTrackerRequestObject) (EditTrackerResponseObject, error)
	// A tracker's entries, newest first
	// (GET /v1/trackers/{trackerId}/entries)
	ListTrackerEntries(ctx context.Context, request ListTrackerEntriesRequestObject) (ListTrackerEntriesResponseObject, error)
	// Pause a tracker (admin only)
	// (POST /v1/trackers/{trackerId}/pause)
	PauseTracker(ctx context.Context, request PauseTrackerRequestObject) (PauseTrackerResponseObject, error)
	// Resume a paused tracker (admin only)
	// (POST /v1/trackers/{trackerId}/resume)
	ResumeTracker(ctx context.Context, request ResumeTrackerRequestObject) (ResumeTrackerResponseObject, error)
	// A tracker's schedules, readable by anyone on the team
	// (GET /v1/trackers/{trackerId}/schedules)
	ListTrackerSchedules(ctx context.Context, request ListTrackerSchedulesRequestObject) (ListTrackerSchedulesResponseObject, error)
	// A schedule's Save, for a new schedule (admin only)
	// (POST /v1/trackers/{trackerId}/schedules)
	AddSchedule(ctx context.Context, request AddScheduleRequestObject) (AddScheduleResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

